CREATE TABLE IF NOT EXISTS guild_spend_refreshes (
    RefreshId TEXT NOT NULL PRIMARY KEY CHECK(typeof(RefreshId)='text' AND RefreshId=upper(RefreshId) AND length(RefreshId)=36 AND substr(RefreshId,9,1)='-' AND substr(RefreshId,14,1)='-' AND substr(RefreshId,19,1)='-' AND substr(RefreshId,24,1)='-' AND length(replace(RefreshId,'-',''))=32 AND replace(RefreshId,'-','') NOT GLOB '*[^0-9A-F]*' AND RefreshId<>'00000000-0000-0000-0000-000000000000'),
    EffectId TEXT NOT NULL REFERENCES guild_spend_sources(EffectId) ON DELETE RESTRICT CHECK(typeof(EffectId)='text' AND EffectId=upper(EffectId) AND length(EffectId)=36 AND substr(EffectId,9,1)='-' AND substr(EffectId,14,1)='-' AND substr(EffectId,19,1)='-' AND substr(EffectId,24,1)='-' AND length(replace(EffectId,'-',''))=32 AND replace(EffectId,'-','') NOT GLOB '*[^0-9A-F]*' AND EffectId<>'00000000-0000-0000-0000-000000000000'),
    OperationId TEXT NOT NULL UNIQUE REFERENCES LongRunningOperations(Id) ON DELETE RESTRICT CHECK(typeof(OperationId)='text' AND OperationId=lower(OperationId) AND length(OperationId)=32 AND OperationId NOT GLOB '*[^0-9a-f]*' AND OperationId<>'00000000000000000000000000000000'),
    RequestDigest BLOB NOT NULL CHECK(typeof(RequestDigest)='blob' AND length(RequestDigest)=32),
    AcceptedReceiptId TEXT NULL REFERENCES guild_spend_receipts(ReceiptId) ON DELETE RESTRICT CHECK(AcceptedReceiptId IS NULL OR (typeof(AcceptedReceiptId)='text' AND AcceptedReceiptId=upper(AcceptedReceiptId) AND length(AcceptedReceiptId)=36 AND substr(AcceptedReceiptId,9,1)='-' AND substr(AcceptedReceiptId,14,1)='-' AND substr(AcceptedReceiptId,19,1)='-' AND substr(AcceptedReceiptId,24,1)='-' AND length(replace(AcceptedReceiptId,'-',''))=32 AND replace(AcceptedReceiptId,'-','') NOT GLOB '*[^0-9A-F]*' AND AcceptedReceiptId<>'00000000-0000-0000-0000-000000000000'))
);
